CREATE TABLE rm_party_events (
 id INTEGER PRIMARY KEY,
 party_id TEXT NOT NULL CHECK(length(party_id) BETWEEN 3 AND 64),
 event_type TEXT NOT NULL CHECK(event_type IN ('created','proposed_merge','approved_merge','superseded','linked')),
 canonical_kind TEXT NOT NULL CHECK(canonical_kind IN ('person','organization','public_authority','financial_institution')),
 payload_hash TEXT NOT NULL CHECK(length(payload_hash)=64 AND payload_hash NOT GLOB '*[^0-9a-f]*'),
 canonical_payload TEXT NOT NULL CHECK(length(canonical_payload) BETWEEN 2 AND 65536),
 actor TEXT NOT NULL CHECK(length(actor) BETWEEN 3 AND 160),
 created_at TEXT NOT NULL,
 UNIQUE(party_id,event_type,payload_hash)
);
CREATE TABLE rm_party_identifiers (
 party_id TEXT NOT NULL,
 jurisdiction TEXT NOT NULL CHECK(length(jurisdiction)=2 AND jurisdiction=upper(jurisdiction)),
 identifier_kind TEXT NOT NULL CHECK(identifier_kind IN ('dk_cvr','eu_vat','non_eu')),
 identifier TEXT NOT NULL,
 PRIMARY KEY(jurisdiction,identifier_kind,identifier),
 UNIQUE(party_id,jurisdiction,identifier_kind,identifier)
);
CREATE TABLE rm_party_company_roles (
 party_id TEXT NOT NULL, company_slug TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('customer','vendor','owner','adviser','employee','authority','bank')),
 defaults_json TEXT NOT NULL DEFAULT '{}',
 PRIMARY KEY(party_id,company_slug,role)
);
CREATE TRIGGER rm_party_events_no_update BEFORE UPDATE ON rm_party_events BEGIN SELECT RAISE(ABORT, 'party events are append-only'); END;
CREATE TRIGGER rm_party_events_no_delete BEFORE DELETE ON rm_party_events BEGIN SELECT RAISE(ABORT, 'party events are append-only'); END;
